CREATE POLICY "CMS editors can upload media" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'cms-media' AND (public.has_role(auth.uid(), 'super_admin') OR public.has_role(auth.uid(), 'admin') OR public.has_role(auth.uid(), 'publisher') OR public.has_role(auth.uid(), 'content_editor') OR public.has_role(auth.uid(), 'commerce_manager')));
CREATE POLICY "CMS editors can read media" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'cms-media' AND (public.has_role(auth.uid(), 'super_admin') OR public.has_role(auth.uid(), 'admin') OR public.has_role(auth.uid(), 'publisher') OR public.has_role(auth.uid(), 'content_editor') OR public.has_role(auth.uid(), 'commerce_manager')));